                sys.exit(1)
        elif arg in ['--minPasswordLen']:
            if i + 1 < len(args_list):
                try:
                    minPasswordLen = int(args_list[i + 1])
                except ValueError:
                    print(f"Error: --minPasswordLen requires an integer value", file=sys.stderr)
                    sys.exit(1)
                i += 2
            else:
                print("Error: --minPasswordLen requires a value", file=sys.stderr)
                sys.exit(1)
        elif arg in ['--maxPasswordLen']:
            if i + 1 < len(args_list):
                try:
                    maxPasswordLen = int(args_list[i + 1])
                except ValueError:
                    print(f"Error: --maxPasswordLen requires an integer value", file=sys.stderr)
                    sys.exit(1)
                i += 2
            else:
                print("Error: --maxPasswordLen requires a value", file=sys.stderr)
                sys.exit(1)
        elif arg in ['--fileNumber']:
            if i + 1 < len(args_list):
                try:
                    fileNumber = int(args_list[i + 1])
                except ValueError:
                    print(f"Error: --fileNumber requires an integer value", file=sys.stderr)
