    # Check if input file exists
    if not os.path.exists(inputFile):
        print(f"Error: Input file not found: {inputFile}", file=sys.stderr)
        sys.exit(1)

    # Check if password dictionary exists
    if passwordDictionary and not os.path.exists(passwordDictionary):
        print(f"Error: Password dictionary not found: {passwordDictionary}", file=sys.stderr)
        sys.exit(1)

    # Validate password length range
    if minPasswordLen < 1:
        print("Error: --minPasswordLen must be at least 1", file=sys.stderr)
        sys.exit(1)
    if maxPasswordLen < minPasswordLen:
        print("Error: --maxPasswordLen must be at least --minPasswordLen", file=sys.stderr)
        sys.exit(1)
    if maxPasswordLen > 100:
        print("Error: --maxPasswordLen must be at most 100", file=sys.stderr)
        sys.exit(1)

    # Start timing
    start_time = time.time()

    # Load passwords from dictionary if specified
    passwords = []
    if passwordDictionary:
        try:
            with open(passwordDictionary, 'r') as f:
                for line in f:
                    password = line.strip()
                    if password:
                        passwords.append(password)
        except Exception as e:
            print(f"Error reading password dictionary: {e}", file=sys.stderr)
            sys.exit(1)

    # Generate passwords if not using dictionary
    if not passwords:
        passwords = generate_passwords(charset, minPasswordLen, maxPasswordLen, startingPassword)

    if not passwords:
        print("Error: No passwords to test", file=sys.stderr)
        sys.exit(1)

    # Test passwords
    results = {'found': None, 'elapsed': 0}
    lock = threading.Lock()

    if workers > 1:
        # Use thread pool
        class ArgsWrapper:
            def __init__(self, args_list):
                self.inputFile = args_list[0]
                self.fileNumber = args_list[1]
                self.start_time = start_time

        args_wrapper = ArgsWrapper([inputFile, fileNumber])
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = []
            for password in passwords:
                future = executor.submit(worker, args_wrapper, [password], results, lock)
                futures.append(future)

            for future in as_completed(futures):
                future.result()
    else:
        # Single worker
        class ArgsWrapper:
            def __init__(self, args_list):
                self.inputFile = args_list[0]
                self.fileNumber = args_list[1]
                self.start_time = start_time

        args_wrapper = ArgsWrapper([inputFile, fileNumber])
        worker(args_wrapper, passwords, results, lock)

    # Print results
    elapsed = results['elapsed']
    if elapsed < 1:
        print(f"Time elapsed: {elapsed * 1000000:.0f}us {elapsed * 1000:.0f}ns")
    elif elapsed < 60:
        print(f"Time elapsed: {elapsed:.0f}s {elapsed * 1000:.0f}ms {elapsed * 1000000:.0f}us {elapsed * 1000000000:.0f}ns")
    else:
        print(f"Time elapsed: {elapsed:.0f}s {elapsed * 1000:.0f}ms {elapsed * 1000000:.0f}us {elapsed * 1000000000:.0f}ns")

    if results['found']:
        print(f"Password found:{results['found']}")
        sys.exit(0)
    else:
        print("Password not found")
        sys.exit(1)

if __name__ == '__main__':
