#!/usr/bin/env python3
"""zip-password-finder - Find the password of protected ZIP files"""

import argparse
import sys
import os
import time
import zipfile
import threading
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import List, Optional, Tuple

# Character sets
CHARSETS = {
    'l': 'abcdefghijklmnopqrstuvwxyz',
    'u': 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    'd': '0123456789',
    'h': '0123456789abcdef',
    'H': '0123456789ABCDEF',
    's': 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?'
}

def load_charset_from_file(filepath: str) -> str:
    """Load charset from a file, one character per line"""
    with open(filepath, 'r') as f:
        content = f.read()
    # Remove empty lines and whitespace-only lines
    chars = [c for c in content if c.strip()]
    return ''.join(chars)

def get_encrypted_files(zip_path: str, file_number: int) -> List[str]:
    """Get list of encrypted files in the ZIP archive"""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            files = []
            for i, name in enumerate(zf.namelist()):
                try:
                    with zf.open(name) as f:
                        f.read(1)  # Try to read to check if encrypted
                except RuntimeError as e:
                    if "encrypted" in str(e).lower():
                        files.append((i, name))
            if file_number >= 0 and file_number < len(files):
                return [files[file_number][1]]
            return [f[1] for f in files]
    except Exception as e:
        print(f"Invalid zip file error - {e}", file=sys.stderr)
        sys.exit(1)

def test_password(zip_path: str, password: bytes, file_number: int) -> bool:
    """Test if a password works for the ZIP file"""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for i, name in enumerate(zf.namelist()):
                try:
                    with zf.open(name, pwd=password) as f:
                        f.read(1)
                except RuntimeError:
                    return False
        return True
    except Exception:
        return False

def generate_passwords(charset: str, min_len: int, max_len: int, start_password: Optional[str] = None) -> List[str]:
    """Generate passwords based on charset and length range"""
    if not charset:
        return []

    chars = list(charset)
    if not chars:
        return []

    passwords = []
    if start_password:
        # Start from start_password and generate variations
        passwords = [start_password]
        # Generate passwords of increasing length
        for length in range(len(start_password), max_len + 1):
            for i in range(len(charset)):
                new_pass = start_password[:i] + chars[i % len(chars)] + start_password[i:]
                if len(new_pass) <= max_len:
                    passwords.append(new_pass)
    else:
        # Generate all passwords from min_len to max_len
        for length in range(min_len, max_len + 1):
            for i in range(len(chars) ** length):
                password = []
                temp = i
                for _ in range(length):
                    password.insert(0, chars[temp % len(chars)])
                    temp //= len(chars)
                passwords.append(''.join(password))

    return passwords

def worker(args, passwords: List[str], results: dict, lock: threading.Lock):
    """Worker function to test passwords"""
    for password in passwords:
        if test_password(args.inputFile, password.encode(), args.fileNumber):
            with lock:
                results['found'] = password
                results['elapsed'] = time.time() - args.start_time
            return

def main():
    # Handle --version before parsing arguments
    if '--version' in sys.argv:
        print("zip-password-finder 0.10.3")
        sys.exit(0)

    parser = argparse.ArgumentParser(
        description='Find the password of protected ZIP files',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='''
Examples:
  zip-password-finder --inputFile secret.zip --passwordDictionary words.txt
  zip-password-finder --inputFile secret.zip --charset l --minPasswordLen 1 --maxPasswordLen 6
'''
    )

    parser.add_argument('-i', '--inputFile', required=True, help='path to zip input file')
    parser.add_argument('-w', '--workers', type=int, default=1, help='number of workers')
    parser.add_argument('-p', '--passwordDictionary', help='path to a password dictionary file')
    parser.add_argument('-c', '--charset', default='lud', help='charset to use to generate password')
    parser.add_argument('--charsetFile', help='path to a charset file')
    parser.add_argument('--minPasswordLen', type=int, default=1, help='minimum password length')
    parser.add_argument('--maxPasswordLen', type=int, default=10, help='maximum password length')
    parser.add_argument('--fileNumber', type=int, default=0, help='file number in the zip archive')
    parser.add_argument('-s', '--startingPassword', help='password to start from')

    # Custom handling for -h flag
    args = parser.parse_args()

    # Handle help
    if hasattr(args, 'help') and args.help:
        parser.print_help()
        sys.exit(0)

    # Validate input file
    if not os.path.exists(args.inputFile):
        print(f'CLI argument error - "{args.inputFile}" does not exist', file=sys.stderr)
        sys.exit(1)

    # Validate charset file
    if args.charsetFile and not os.path.exists(args.charsetFile):
        print(f'CLI argument error - "{args.charsetFile}" does not exist', file=sys.stderr)
        sys.exit(1)

    # Determine charset
    if args.charsetFile:
        charset = load_charset_from_file(args.charsetFile)
    else:
        # Check if charset is valid
        if args.charset not in CHARSETS:
            print(f'CLI argument error - "Unknown charset option {args.charset}"', file=sys.stderr)
            sys.exit(1)
        charset = CHARSETS[args.charset]

    # Validate charset
    if not charset:
        print(f'CLI argument error - "Unknown charset option {args.charset}"', file=sys.stderr)
        sys.exit(1)

    # Validate starting password
    if args.startingPassword:
        if args.passwordDictionary:
            print(f'CLI argument error - "{args.startingPassword}" cannot be used with a dictionary file', file=sys.stderr)
            sys.exit(1)

        # Check if starting password uses characters from the charset
        for char in args.startingPassword:
            if char not in charset:
                print(f'CLI argument error - "{args.startingPassword}" uses characters out of the generation charset', file=sys.stderr)
                sys.exit(1)

    # Get encrypted files
    encrypted_files = get_encrypted_files(args.inputFile, args.fileNumber)
    if not encrypted_files:
        print(f'Invalid zip file error - no encrypted files found in archive (file_number:{args.fileNumber})', file=sys.stderr)
        sys.exit(1)

    # Load dictionary if provided
    passwords = []
    if args.passwordDictionary:
        if not os.path.exists(args.passwordDictionary):
            print(f'CLI argument error - "{args.passwordDictionary}" does not exist', file=sys.stderr)
            sys.exit(1)

        with open(args.passwordDictionary, 'r') as f:
            passwords = [line.rstrip('\n\r') for line in f if line.strip()]
    else:
        # Generate passwords
        passwords = generate_passwords(charset, args.minPasswordLen, args.maxPasswordLen, args.startingPassword)

    if not passwords:
        print(f'CLI argument error - no passwords to test', file=sys.stderr)
        sys.exit(1)

    # Start timing
    start_time = time.time()
    args.start_time = start_time

    # Test passwords
    found = None
    results = {'found': None, 'elapsed': 0}
    lock = threading.Lock()

    if args.workers > 1:
        with ThreadPoolExecutor(max_workers=args.workers) as executor:
            futures = []
            for _ in encrypted_files:
                future = executor.submit(worker, args, passwords, results, lock)
                futures.append(future)

            for future in as_completed(futures):
                try:
                    future.result()
                except Exception:
                    pass
    else:
        worker(args, passwords, results, lock)

    elapsed = time.time() - start_time

    if results['found']:
        print(f"Time elapsed: {elapsed:.6f}s")
        print(f"Password found:{results['found']}")
        sys.exit(0)
    else:
        print(f"Time elapsed: {elapsed:.6f}s")
        print("Password not found")
        sys.exit(0)

if __name__ == '__main__':
    main()
