'''
    )
    parser.add_argument('-i', '--inputFile', required=True, help='path to zip input file')
    parser.add_argument('-w', '--workers', type=int, default=1, help='number of workers')
    parser.add_argument('-p', '--passwordDictionary', help='path to a password dictionary file')
    parser.add_argument('-c', '--charset', default='lud', help='charset to use to generate password')
    parser.add_argument('--charsetFile', help='path to a charset file')
    parser.add_argument('--minPasswordLen', type=int, default=1, help='minimum password length')
    parser.add_argument('--maxPasswordLen', type=int, default=10, help='maximum password length')
    parser.add_argument('--fileNumber', type=int, default=0, help='file number in the zip archive')
    parser.add_argument('-s', '--startingPassword', help='password to start from')
    parser.add_argument('--version', action='store_true', help='Print version')

    args = parser.parse_args()

    if args.version:
        print('zip-password-finder 0.10.3')
        sys.exit(0)

    return args

def load_charset(charset_str: str) -> str:
    """Load charset from string or file"""
    if not charset_str:
        return ''

    # Check if it's a file path
    try:
        with open(charset_str, 'r') as f:
            content = f.read()
            # Handle both newline-separated and space-separated
            chars = set()
            for line in content.split('\n'):
                line = line.strip()
                if line:
                    chars.update(line)
            return ''.join(sorted(chars))
    except FileNotFoundError:
        pass

    # Treat as charset string
    return charset_str

def get_charset(charset_arg: str, charset_file: Optional[str]) -> str:
    """Get the final charset to use"""
    if charset_file:
        return load_charset(charset_file)
    # If it's a known single-char key, use it; otherwise combine known chars
    if charset_arg in CHARSETS:
        return CHARSETS[charset_arg]
    # For combined charsets like 'lud', combine them
    result = ''
    for c in charset_arg:
        if c in CHARSETS:
            result += CHARSETS[c]
    return result

def generate_password_iterator(charset: str, min_len: int, max_len: int, starting_password: Optional[str] = None):
    """Generate passwords one at a time"""
    if not charset:
        return

    # Generate all passwords
    passwords = []
    for length in range(min_len, max_len + 1):
        for combo in itertools.product(charset, repeat=length):
            passwords.append(''.join(combo))

    if starting_password:
        if starting_password not in passwords:
            # Insert starting password at the beginning
            passwords.insert(0, starting_password)

    for p in passwords:
        yield p

def test_password(zip_path: str, password: str, file_number: int) -> bool:
    """Test if a password works for the specified file in the zip"""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Try to open the specific file
            if file_number >= 0 and file_number < len(zf.namelist()):
                target_file = zf.namelist()[file_number]
                try:
                    zf.extract(target_file, path='/tmp', pwd=password.encode())
                    return True
                except:
                    return False
            else:
                # Try all files
                for name in zf.namelist():
                    try:
                        zf.extract(name, path='/tmp', pwd=password.encode())
                        return True
                    except:
                        continue
        return False
    except:
        return False

def dictionary_attack(zip_path: str, dictionary_path: str, file_number: int) -> Optional[str]:
    """Perform dictionary attack"""
    try:
        with open(dictionary_path, 'r') as f:
            passwords = [line.strip() for line in f if line.strip()]
    except:
        return None

    for password in passwords:
        if test_password(zip_path, password, file_number):
            return password
    return None

def brute_force_attack(zip_path: str, charset: str, min_len: int, max_len: int, 
                       file_number: int, starting_password: Optional[str] = None,
                       workers: int = 1) -> Optional[str]:
    """Perform brute force attack"""
    if not charset:
        return None

    results = [None]
    lock = threading.Lock()

    def worker():
        for password in generate_password_iterator(charset, min_len, max_len, starting_password):
            if results[0] is not None:
                break
            if test_password(zip_path, password, file_number):
                with lock:
                    results[0] = password
                break

    threads = []
    for _ in range(workers):
        t = threading.Thread(target=worker)
        t.start()
        threads.append(t)

    for t in threads:
        t.join()

    return results[0]

def main():
    args = parse_args()

    # Get charset
    charset = get_charset(args.charset, args.charsetFile)

    # Validate starting password if provided
    if args.startingPassword:
        if not charset:
            print('CLI argument error - "startingPassword uses characters out of the generation charset"', file=sys.stderr)
            sys.exit(1)
        if not all(c in charset for c in args.startingPassword):
            print(f'CLI argument error - "{args.startingPassword} uses characters out of the generation charset"', file=sys.stderr)
            sys.exit(1)

    # Test if file exists
    try:
        with open(args.inputFile, 'rb') as f:
