{"command": "python3 -c "
import time

CHARSETS = {
    'l': 'abcdefghijklmnopqrstuvwxyz',
}

def get_charset(charset):
    result = ''
    for c in charset:
        if c in CHARSETS:
            result += CHARSETS[c]
    return result

def generate_password_iterator(min_len, max_len, charset):
    charset_str = get_charset(charset)
    for length in range(min_len, max_len + 1):
        for i in range(len(charset_str) ** length):
            yield ''.join([charset_str[(i // (len(charset_str) ** j)) % len(charset_str)] for j in range(length)])

# Test with min=1, max=4
start = time.time()
count = 0
for pwd in generate_password_iterator(1, 4, 'l'):
    count += 1
    if count == 1000000:
        break
end = time.time()
print(f'Generated {count} passwords in {end - start:.2f}s')
