import time
import itertools

CHARSETS = {
    'l': 'abcdefghijklmnopqrstuvwxyz',
}

def get_charset(charset):
    result = ''
    for c in charset:
        if c in CHARSETS:
            result += CHARSETS[c]
    return result

def generate_password_iterator_v2(min_len, max_len, charset):
    """Optimized password generator using itertools."""
    charset_str = get_charset(charset)
    for length in range(min_len, max_len + 1):
        for combo in itertools.product(charset_str, repeat=length):
            yield ''.join(combo)

# Test with min=1, max=4
start = time.time()
count = 0
for pwd in generate_password_iterator_v2(1, 4, 'l'):
    count += 1
    if count == 1000000:
        break
end = time.time()
print(f'Generated {count} passwords in {end - start:.2f}s')
EOF
